data.query:
query Query($where: PurchaseOrderWhereInput, $orderBy: [PurchaseOrderOrderByInput!], $first: Int, $after: String) {
  po:purchaseOrder(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        externalId
        note
        shipmentNumber
        issuedAt
        customData
        integrationData
        purchaseOrderType{id name}
        supplier{id code}
        facility{id code}
        purchaseOrderStatus{id name active}

      }
    }
  }
}

query Query($where: PurchaseOrderWhereInput, $orderBy: [PurchaseOrderOrderByInput!], $first: Int, $after: String) {
  po:purchaseOrder(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {

        lines{total}
        receipts{total}

      }
    }
  }
}

query Query($where: PurchaseOrderWhereInput, $orderBy: [PurchaseOrderOrderByInput!], $first: Int, $after: String) {
  po:purchaseOrder(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        purchaseOrderStatus{active}
        number
      }
    }
  }
}

data.variablesTransform:
{
  "payload": {
    "create": {
      "expectedReceiptAt": expectedReceiptAt,

      "purchaseOrderLineStatusId": purchaseOrderLineStatus.id,
      "purchaseOrderId": purchaseOrder.id,
      "productId": product.id,
      "productStrategyProcessId": productStrategyProcess.id,
      "description":description,
      "quantity":{
        "value":quantity.value,
        "unitId": quantity.unit.id
      },
      "balanceQuantity":{
        "value":quantity.value,
        "unitId": quantity.unit.id
      },
      "pendingQuantity": {
        "value":0,
        "unitId": quantity.unit.id
      },
      "receivedQuantity":{
        "value":0,
        "unitId": quantity.unit.id
      }
    }
  }
}

data.query:
query Query($where: PurchaseOrderLineWhereInput, $orderBy: [PurchaseOrderLineOrderByInput!], $first: Int, $after: String) {
  pol:purchaseOrderLine(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        code
        description
        externalId
        number
        expectedReceiptAt
        purchaseOrder{id number}
        purchaseOrderLineStatus{id name active}
        product{id code}
        productStrategyProcess{id code}
        quantity{value unit{id code}}
        balanceQuantity {value unit{id code}}
        pendingQuantity  {value unit{id code}}
        receivedQuantity {value unit{id code}}
        revisedQuantity {value unit{id code}}
      }
    }
  }
}

data.variablesTransform:
{
  "payload": {
    "update": $isNilOrEmpty(revisedQuantity.value) ? {
      "purchaseOrderLineStatusId": purchaseOrderLineStatus.id,
      "description":description,
      "expectedReceiptAt": expectedReceiptAt
    } : {
      "purchaseOrderLineStatusId": purchaseOrderLineStatus.id,
      "description":description,
      "expectedReceiptAt": expectedReceiptAt,
      "revisedQuantity": {
        "quantity": revisedQuantity.value,
        "unitId": quantity.unit.id
      }
    },"where":{
      "id": $state.context.REQUEST.DATA.id
    }
  }
}

